package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes: the original implementation was a single
// character-by-character loop that mixed headers, list items, paragraphs and
// emphasis together, tracked with opaque flags ("he", "list", "listOpened")
// and string-search hacks. It has been rewritten as a line-oriented parser:
//
//  1. Emphasis markers are translated up front (see translateEmphasis).
//  2. The document is split into lines and each line is classified as a
//     header, a list item, or a paragraph.
//  3. Consecutive list items are wrapped in a single <ul> element that is
//     opened on the first item and closed when the list ends.
//
// The rendered output for the supported syntax is unchanged.
func Render(markdown string) string {
	markdown = translateEmphasis(markdown)

	var html strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		// A list ends as soon as a non-list line appears.
		if inList && !isListItem(line) {
			html.WriteString("</ul>")
			inList = false
		}

		switch {
		case isHeader(line):
			html.WriteString(renderHeader(line))
		case isListItem(line):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + listItemText(line) + "</li>")
		default:
			html.WriteString("<p>" + line + "</p>")
		}
	}
	if inList {
		html.WriteString("</ul>")
	}
	return html.String()
}

// translateEmphasis converts the first "__...__" pair to a <strong> element
// and the first "_..._" pair to an <em> element.
//
// The original implementation translated only the first pair of each marker
// (strings.Replace with a count of 1); this helper keeps that behaviour but
// makes the intent explicit.
func translateEmphasis(markdown string) string {
	markdown = replaceFirst(markdown, "__", "<strong>")
	markdown = replaceFirst(markdown, "__", "</strong>")
	markdown = replaceFirst(markdown, "_", "<em>")
	markdown = replaceFirst(markdown, "_", "</em>")
	return markdown
}

// replaceFirst returns s with only the first occurrence of old replaced by
// new. It is equivalent to strings.Replace(s, old, new, 1).
func replaceFirst(s, old, new string) string {
	i := strings.Index(s, old)
	if i < 0 {
		return s
	}
	return s[:i] + new + s[i+len(old):]
}

// headerLevel reports whether line is a header, and if so its level.
//
// A header starts with one to six '#' characters. Lines with seven or more
// leading '#' characters are not valid headers (there is no <h7>), so they
// are treated as ordinary paragraphs.
func headerLevel(line string) (int, bool) {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	return level, level > 0 && level <= 6
}

// isHeader reports whether line is a header.
func isHeader(line string) bool {
	_, ok := headerLevel(line)
	return ok
}

// renderHeader renders a header line as an <hN> element, where N is the
// number of leading '#' characters. The text is the remainder of the line
// without the separating space.
func renderHeader(line string) string {
	level, _ := headerLevel(line)
	text := strings.TrimPrefix(line[level:], " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, text, level)
}

// isListItem reports whether line is an unordered list item, i.e. it starts
// with "* ".
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// listItemText returns the text of a list item without its "* " marker.
func listItemText(line string) string {
	return strings.TrimPrefix(line, "* ")
}
